-- Hand-written backfills.
-- bookings.list_price_paise: the flat price offered at booking time, already frozen in flat_snapshot.
UPDATE "bookings" SET "list_price_paise" = round(("flat_snapshot" ->> 'price_paise')::numeric)::bigint
  WHERE "list_price_paise" IS NULL AND ("flat_snapshot" ->> 'price_paise') IS NOT NULL;--> statement-breakpoint
-- site_visits.manage_token_expires_at: existing manage links stop working one day after the visit slot ends (IST).
UPDATE "site_visits" SET "manage_token_expires_at" = (("visit_date" + "slot_end") AT TIME ZONE 'Asia/Kolkata') + interval '1 day'
  WHERE "manage_token_hash" IS NOT NULL AND "manage_token_expires_at" IS NULL;
